import{apiClient}from"./client";const getCars=async a=>{return(await apiClient.get("/carList?organizationSlug=hyundai-kyiv",{params:a?{organizationSlug:a}:{}})).data.items},getCarByVin=async(a,i)=>{return(await apiClient.get(`/carList/${a}?organizationSlug=hyundai-kyiv`,{params:{organizationSlug:i}})).data};export{getCars,getCarByVin};